"""Update only the known four-camera class10 policy/labels; preserve camera color."""
from pathlib import Path
import base64
import datetime
import hashlib
import json
import os

ROOT = Path('/userdata/Cascaded_Four_Camera/Board_RK3568')
OLD = {'Inference_Four_Views/detection_policy.py': 'e02b0668565e508fd64b20bf3863296a470b015ec54b7f6cd1178eb6fe38ec88', 'Inference_Four_Views/quad_infer.py': '14082fc8a2abda611104554665d16484f76fc4fd8895a1d76112e11d2020c924'}
NEW = {'Inference_Four_Views/detection_policy.py': 'f630839f0b0dd4518e434eaf989a2d41a8eb1e387ecb78d412cba963a3cfbbd8', 'Inference_Four_Views/quad_infer.py': '551a3f6eec1b0918d5d4e8f0a29a9e753e5a09627e956a7cd9d6f7c845ecf050'}
PAYLOAD = {'Inference_Four_Views/detection_policy.py': '', 'Inference_Four_Views/quad_infer.py': ''}


def digest(data):
    return hashlib.sha256(data).hexdigest()


def require_idle():
    active = []
    for path in Path('/proc').glob('[0-9]*/cmdline'):
        if int(path.parent.name) == os.getpid():
            continue
        try:
            words = [Path(v.decode(errors='replace')).name for v in path.read_bytes().split(b'\0') if v]
        except OSError:
            continue
        if any(n in ('quad_infer.py', 'quad_view.py', 'cap_reader.py', 'run_vision.py') for n in words):
            active.append(path.parent.name)
    if active:
        raise RuntimeError('First Ctrl+C the capture/inference terminal. Active PID: '+','.join(active))


def atomic_write(path, data):
    temporary = path.with_name(path.name+'.conf040.pending')
    try:
        with temporary.open('wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if temporary.exists():
            temporary.unlink()


def apply(root=ROOT, check_idle=True):
    root = Path(root).resolve()
    if check_idle:
        require_idle()
    manifest = root.parent/'MANIFEST.sha256'
    original_manifest = manifest.read_bytes()
    lines = original_manifest.decode('utf-8').splitlines(keepends=True)
    prepared = {}
    positions = {}
    already = True
    for relative in OLD:
        path = (root/relative).resolve()
        if not path.is_relative_to(root):
            raise RuntimeError('Unexpected target')
        content = path.read_bytes()
        if digest(content) not in (OLD[relative], NEW[relative]):
            raise RuntimeError('Unknown file version, no files changed: '+relative)
        name = 'Board_RK3568/'+relative
        found = [i for i,line in enumerate(lines) if line.rstrip('\r\n').split('  ',1)[-1]==name]
        if len(found)!=1 or lines[found[0]].split('  ',1)[0] not in (OLD[relative],NEW[relative]):
            raise RuntimeError('Unknown manifest entry, no files changed: '+name)
        data = base64.b64decode(PAYLOAD[relative], validate=True)
        if digest(data)!=NEW[relative]:
            raise RuntimeError('Invalid patch payload')
        already = already and digest(content)==NEW[relative] and lines[found[0]].split('  ',1)[0]==NEW[relative]
        prepared[relative] = (path,content,data)
        positions[relative] = found[0]
    if already:
        print('CLASS10_040_ALREADY_INSTALLED; restart START_INFERENCE.sh to load')
        return
    backup = root/'Results/Class10_040_Backups'/datetime.datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backup.mkdir(parents=True)
    (backup/'MANIFEST.before.sha256').write_bytes(original_manifest)
    for relative,(path,content,data) in prepared.items():
        target = backup/relative
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(content)
        atomic_write(path,data)
        index = positions[relative]
        newline = '\r\n' if lines[index].endswith('\r\n') else '\n'
        lines[index] = NEW[relative]+'  Board_RK3568/'+relative+newline
    atomic_write(manifest,''.join(lines).encode('utf-8'))
    print('CLASS10_UPDATE_OK '+json.dumps({'class10':.40,'other_classes':.25,
        'camera_color_changed':False,'model_weights_changed':False,'backup':str(backup)},ensure_ascii=False))
    print('Run bash ./START_INFERENCE.sh; /stat must show class10_min_confidence=0.4')


if __name__=='__main__':
    if os.name!='posix':
        raise SystemExit('Run this updater on the RK3568; the PC submission is already updated.')
    apply()
